"""Own bilingual voice UI resources; no external data or confidential material."""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
VALUES = {
 'en-US': {'voiceConfiguration': 'Voice configuration', 'telephonyProvider': 'Telephony provider', 'sttProvider': 'Speech recognition provider', 'ttsProvider': 'Speech synthesis provider', 'incomingNumber': 'Incoming phone number', 'voiceSelection': 'Voice ID', 'greeting': 'Greeting', 'callTimeout': 'Maximum call duration (seconds)', 'silenceTimeout': 'Silence timeout (seconds)', 'latencyLimit': 'Turn latency limit (milliseconds)', 'humanNumber': 'Human escalation number', 'lawfulBasis': 'Configured privacy policy basis', 'consent': 'Consent', 'contract': 'Contract', 'legitimate_interests': 'Legitimate interests', 'connectAudio': 'Connect synthetic audio stream', 'sendAudioFixture': 'Send synthetic audio fixture', 'twilio': 'Twilio · live adapter unverified', 'azure': 'Azure Speech · live adapter unverified', 'LIVE_UNVERIFIED': 'LIVE · UNVERIFIED', 'unsupported_audio': 'This provider does not support the supplied audio format.', 'voice:retention_redacted': 'Expired voice content redacted', 'telephony:configured': 'Telephony configured', 'call:consent': 'Caller consent recorded', 'call:ended': 'Call ended', 'call:failed': 'Call failed', 'call:transferred': 'Call transferred', 'call:listening': 'Call listening'},
 'bg-BG': {'voiceConfiguration': 'Настройки на гласа', 'telephonyProvider': 'Доставчик на телефония', 'sttProvider': 'Доставчик на разпознаване на говор', 'ttsProvider': 'Доставчик на синтез на говор', 'incomingNumber': 'Входящ телефонен номер', 'voiceSelection': 'Идентификатор на гласа', 'greeting': 'Поздрав', 'callTimeout': 'Максимална продължителност (секунди)', 'silenceTimeout': 'Лимит при тишина (секунди)', 'latencyLimit': 'Лимит за отговор (милисекунди)', 'humanNumber': 'Номер за връзка с човек', 'lawfulBasis': 'Настроено основание за личните данни', 'consent': 'Съгласие', 'contract': 'Договор', 'legitimate_interests': 'Легитимен интерес', 'connectAudio': 'Свързване на тестов аудиопоток', 'sendAudioFixture': 'Изпращане на тестово аудио', 'twilio': 'Twilio · реалният адаптер не е проверен', 'azure': 'Azure Speech · реалният адаптер не е проверен', 'LIVE_UNVERIFIED': 'РЕАЛЕН · НЕПРОВЕРЕН', 'unsupported_audio': 'Доставчикът не поддържа този аудиоформат.', 'voice:retention_redacted': 'Заличено гласово съдържание с изтекъл срок', 'telephony:configured': 'Настроена телефония', 'call:consent': 'Отбелязано съгласие на обаждащия се', 'call:ended': 'Приключило обаждане', 'call:failed': 'Неуспешно обаждане', 'call:transferred': 'Прехвърлено обаждане', 'call:listening': 'Слушане на обаждане'}
}
for locale, values in VALUES.items():
    path = ROOT / f'semantic_os/frontend/src/locales/{locale}.json'
    resources = json.loads(path.read_text(encoding='utf-8'))
    resources.update(values)
    resources['mockNotice'] = ('Development foundation: the LLM, calendar and default channels are mocked. Live voice adapters require explicit configuration and verification.'
        if locale == 'en-US' else 'Среда за разработка: езиковият модел, календарът и основните канали са симулирани. Реалните гласови адаптери изискват изрична настройка и проверка.')
    path.write_text(json.dumps(resources, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
